-- Barbarg core data schema; applied to Supabase project ufejrknhkwrtvfesxbbp.
-- All exposed tables use owner-scoped RLS. UTCMS service credentials are never stored here.
create table public.profiles (id uuid primary key references auth.users(id) on delete cascade, national_code text unique, mobile text, display_name text not null default '', created_at timestamptz not null default now(), updated_at timestamptz not null default now(), constraint profiles_national_code_format check (national_code is null or national_code ~ '^[0-9]{10}$'), constraint profiles_mobile_format check (mobile is null or mobile ~ '^09[0-9]{9}$'));
create table public.vehicles (id uuid primary key default gen_random_uuid(), owner_id uuid not null references auth.users(id) on delete cascade, local_key text, plate_id text not null, plate_type text, vehicle_type text, capacity numeric(14,3), metadata jsonb not null default '{}'::jsonb, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(owner_id, plate_id));
create index vehicles_owner_updated_idx on public.vehicles(owner_id, updated_at desc);
create table public.drivers (id uuid primary key default gen_random_uuid(), owner_id uuid not null references auth.users(id) on delete cascade, local_key text, national_code text not null, mobile text, full_name text not null default '', metadata jsonb not null default '{}'::jsonb, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(owner_id, national_code), constraint drivers_national_code_format check (national_code ~ '^[0-9]{10}$'), constraint drivers_mobile_format check (mobile is null or mobile ~ '^09[0-9]{9}$'));
create index drivers_owner_updated_idx on public.drivers(owner_id, updated_at desc);
create table public.cargo_items (id uuid primary key default gen_random_uuid(), owner_id uuid not null references auth.users(id) on delete cascade, local_key text, title text not null, goods_code text, metadata jsonb not null default '{}'::jsonb, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create index cargo_items_owner_updated_idx on public.cargo_items(owner_id, updated_at desc);
create table public.routes (id uuid primary key default gen_random_uuid(), owner_id uuid not null references auth.users(id) on delete cascade, local_key text, origin text, destination text, metadata jsonb not null default '{}'::jsonb, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create index routes_owner_updated_idx on public.routes(owner_id, updated_at desc);
create table public.bol_issuances (id uuid primary key default gen_random_uuid(), owner_id uuid not null references auth.users(id) on delete cascade, local_trace_code text, trace_code text, status text not null default 'PENDING', request_payload jsonb not null, response_payload jsonb, error_code text, error_message text, issued_at timestamptz, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), constraint bol_status_check check (status in ('PENDING','SUBMITTED','ISSUED','FAILED','STARTED','ENDED')));
create index bol_issuances_owner_created_idx on public.bol_issuances(owner_id, created_at desc);
create unique index bol_issuances_owner_trace_uidx on public.bol_issuances(owner_id, trace_code) where trace_code is not null;
create table public.audit_events (id bigint generated always as identity primary key, owner_id uuid not null references auth.users(id) on delete cascade, event_type text not null, entity_type text not null, entity_id uuid, details jsonb not null default '{}'::jsonb, created_at timestamptz not null default now());
create index audit_events_owner_created_idx on public.audit_events(owner_id, created_at desc);
alter table public.profiles enable row level security;
alter table public.vehicles enable row level security;
alter table public.drivers enable row level security;
alter table public.cargo_items enable row level security;
alter table public.routes enable row level security;
alter table public.bol_issuances enable row level security;
alter table public.audit_events enable row level security;
create policy profile_select_own on public.profiles for select to authenticated using ((select auth.uid()) = id);
create policy profile_insert_own on public.profiles for insert to authenticated with check ((select auth.uid()) = id);
create policy profile_update_own on public.profiles for update to authenticated using ((select auth.uid()) = id) with check ((select auth.uid()) = id);
create policy vehicles_select_own on public.vehicles for select to authenticated using ((select auth.uid()) = owner_id);
create policy vehicles_insert_own on public.vehicles for insert to authenticated with check ((select auth.uid()) = owner_id);
create policy vehicles_update_own on public.vehicles for update to authenticated using ((select auth.uid()) = owner_id) with check ((select auth.uid()) = owner_id);
create policy vehicles_delete_own on public.vehicles for delete to authenticated using ((select auth.uid()) = owner_id);
create policy drivers_select_own on public.drivers for select to authenticated using ((select auth.uid()) = owner_id);
create policy drivers_insert_own on public.drivers for insert to authenticated with check ((select auth.uid()) = owner_id);
create policy drivers_update_own on public.drivers for update to authenticated using ((select auth.uid()) = owner_id) with check ((select auth.uid()) = owner_id);
create policy drivers_delete_own on public.drivers for delete to authenticated using ((select auth.uid()) = owner_id);
create policy cargo_select_own on public.cargo_items for select to authenticated using ((select auth.uid()) = owner_id);
create policy cargo_insert_own on public.cargo_items for insert to authenticated with check ((select auth.uid()) = owner_id);
create policy cargo_update_own on public.cargo_items for update to authenticated using ((select auth.uid()) = owner_id) with check ((select auth.uid()) = owner_id);
create policy cargo_delete_own on public.cargo_items for delete to authenticated using ((select auth.uid()) = owner_id);
create policy routes_select_own on public.routes for select to authenticated using ((select auth.uid()) = owner_id);
create policy routes_insert_own on public.routes for insert to authenticated with check ((select auth.uid()) = owner_id);
create policy routes_update_own on public.routes for update to authenticated using ((select auth.uid()) = owner_id) with check ((select auth.uid()) = owner_id);
create policy routes_delete_own on public.routes for delete to authenticated using ((select auth.uid()) = owner_id);
create policy bol_select_own on public.bol_issuances for select to authenticated using ((select auth.uid()) = owner_id);
create policy bol_insert_own on public.bol_issuances for insert to authenticated with check ((select auth.uid()) = owner_id);
create policy bol_update_own on public.bol_issuances for update to authenticated using ((select auth.uid()) = owner_id) with check ((select auth.uid()) = owner_id);
create policy audit_select_own on public.audit_events for select to authenticated using ((select auth.uid()) = owner_id);
create policy audit_insert_own on public.audit_events for insert to authenticated with check ((select auth.uid()) = owner_id);
grant select, insert, update on public.profiles to authenticated;
grant select, insert, update, delete on public.vehicles, public.drivers, public.cargo_items, public.routes to authenticated;
grant select, insert, update on public.bol_issuances to authenticated;
grant select, insert on public.audit_events to authenticated;
